public class FileItem
{
    public Guid Id { get; } = Guid.NewGuid();
    public string Name { get; set; }
    public Guid? ParentId { get; set; }
    public Guid OwnerId { get; set; }
    public long SizeBytes { get; set; }
    public string ContentHash { get; set; }
    public DateTime CreatedAt { get; } = DateTime.UtcNow;
    public DateTime ModifiedAt { get; set; }
}

public class Permission
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid ItemId { get; set; }
    public Guid GranteeId { get; set; }
    public PermissionLevel Level { get; set; }
}

public enum PermissionLevel { Viewer, Editor, Owner }

public class DriveService
{
    public void Share(Guid itemId, Guid granteeId, PermissionLevel level)
    {
        _permissions.Add(new Permission { ItemId = itemId, GranteeId = granteeId, Level = level });
    }

    public bool HasAccess(Guid userId, Guid itemId, PermissionLevel required)
    {
        var item = _files[itemId];
        if (item.OwnerId == userId) return true;
        var perm = _permissions.FirstOrDefault(p => p.ItemId == itemId && p.GranteeId == userId);
        return perm != null && perm.Level >= required;
    }
}
